/* ---------- drawing helpers for this lesson (prefixed VL_ so they never clash with engine globals) ---------- */
const VL_F='font-family="Nunito Sans, sans-serif"', VL_MF='font-family="IBM Plex Mono, monospace"';
const VL_A='[a](/ˈA/)', VL_AA='[A](/ˈA/)';              /* the letter a / A, never the article */
const VL_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${VL_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}">${t}</text>`;
const VL_M=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${VL_MF} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}" xml:space="preserve">${t}</text>`;
const VL_L=(x1,y1,x2,y2,col='#5C6577',w=3,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const VL_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"${o.dash?` stroke-dasharray="${o.dash}"`:''}/>`;
const VL_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return VL_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
/* a row of bit cells: bits is a string such as '1010' */
const VL_bits=(x,y,bits,col,w=48,h=48,fs=30)=>[...bits].map((b,i)=>VL_box(x+i*(w+4),y,w,h,{r:6,fill:b==='1'?col:'#FFFFFF',st:col,sw:3})+VL_M(x+i*(w+4)+w/2,y+h/2+fs*.36,b,{fs,fw:700,a:'middle',fill:b==='1'?'#FFFFFF':col})).join('');
/* gate outlines: x,y is the top-left corner, h the height */
const VL_and=(x,y,h,col='#18213A',fill='#FFFFFF')=>`<path d="M${x} ${y}h${h*.5}a${h/2} ${h/2} 0 0 1 0 ${h}h${-h*.5}z" fill="${fill}" stroke="${col}" stroke-width="3"/>`;
const VL_or=(x,y,h,col='#18213A',fill='#FFFFFF')=>`<path d="M${x} ${y}q${h*.3} ${h/2} 0 ${h}q${h*.9} 0 ${h*1.2} ${-h/2}q${-h*.3} ${-h/2} ${-h*1.2} ${-h/2}z" fill="${fill}" stroke="${col}" stroke-width="3"/>`;
const VL_not=(x,y,h,col='#18213A')=>`<path d="M${x} ${y}l${h*.8} ${h/2}l${-h*.8} ${h/2}z" fill="#FFFFFF" stroke="${col}" stroke-width="3"/><circle cx="${x+h*.8+6}" cy="${y+h/2}" r="6" fill="#FFFFFF" stroke="${col}" stroke-width="3"/>`;
const VL_mux=(x,y,w,h,col='#18213A',fill='#FFFFFF')=>`<path d="M${x} ${y}L${x+w} ${y+h*.18}V${y+h*.82}L${x} ${y+h}Z" fill="${fill}" stroke="${col}" stroke-width="3"/>`;
const VL_chip=(x,y,big,lab,col)=>VL_box(x,y,130,92,{r:12,fill:'#FFFFFF',st:col,sw:3})+VL_M(x+65,y+46,big,{fs:40,fw:700,a:'middle',fill:col})+VL_T(x+65,y+80,lab,{fs:22,fw:700,a:'middle',fill:'#5C6577'});

